import { DEMO_MODE, routeMaster, demoOperationStatus, demoReservationCapacity, demoBookings, operationLabels, reservationLabels } from './data/config.js';

const app=document.querySelector('#app'),SESSION_KEY='shimatabi-booking-draft-v2';
const labels=['出発方向','片道・往復','乗船日','便','人数','乗船者','確認','決済','完了'];
const isoDate=d=>new Date(Date.now()+d*86400000).toISOString().slice(0,10),addDays=(date,d)=>{const[y,m,day]=date.split('-').map(Number);return new Date(Date.UTC(y,m-1,day+d)).toISOString().slice(0,10)},yen=n=>`${Number(n||0).toLocaleString('ja-JP')}円`,escapeHtml=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])),ferry=()=>document.querySelector('#ferrymaru').innerHTML;
const defaults={routeId:null,step:0,direction:'outbound',trip:'oneWay',date:isoDate(1),returnDate:isoDate(3),sailing:null,returnSailing:null,adult:0,child:0,bookingContact:{name:'',tel:'',email:''},passengers:[],errors:{}};
const saved=(()=>{try{return JSON.parse(sessionStorage.getItem(SESSION_KEY))||{}}catch{return{}}})(),state={...defaults,...saved,bookingContact:{...defaults.bookingContact},passengers:[],errors:{}};
const persist=()=>sessionStorage.setItem(SESSION_KEY,JSON.stringify({routeId:state.routeId,step:state.step,direction:state.direction,trip:state.trip,date:state.date,returnDate:state.returnDate,sailing:state.sailing,returnSailing:state.returnSailing,adult:state.adult,child:state.child}));
const directionInfo=(r,dir=state.direction)=>dir==='outbound'?{from:r.mainlandPort,to:r.islandPort,key:'outbound',reverseKey:'inbound'}:{from:r.islandPort,to:r.mainlandPort,key:'inbound',reverseKey:'outbound'};
const operation=(r,key)=>demoOperationStatus[r.id][key];
function capacity(r,key,i){const c=demoReservationCapacity[r.id][key][i];return{...c,remaining:Math.max(0,r.passengerCapacity-c.reserved-c.held)}}
function bookingStatus(r,key,i){const op=operation(r,key)[i],cap=capacity(r,key,i);if(op.operationStatus==='cancelled')return'unavailable';if(['closed','unavailable'].includes(op.reservationStatus))return op.reservationStatus;if(!cap.remaining)return'full';if(cap.remaining<=10||op.reservationStatus==='few')return'few';return'open'}
function statusBadge(type,label){const cls=['normal','open'].includes(type)?'ok':['changed','few','undecided'].includes(type)?'warn':['cancelled','full'].includes(type)?'bad':'unknown';return`<span class="status ${cls}">${label}</span>`}
function nextDeparture(r){const tokyo=Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Tokyo',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date()).replace(':',''));return operation(r,'outbound').filter(x=>x.operationStatus!=='cancelled'&&Number(x.departure.replace(':',''))>tokyo).sort((a,b)=>a.departure.localeCompare(b.departure))[0]||null}
const durationLabel=m=>m>=60?`約${Math.floor(m/60)}時間${m%60?`${m%60}分`:''}`:`約${m}分`;

function home(){document.body.classList.remove('admin-mode');document.querySelector('.brand-label').textContent='島旅フェリー予約';location.hash='user';app.innerHTML=`<div class="screen home-screen"><section class="hero"><div class="hero-inner"><span class="eyebrow">伊平屋・伊是名 フェリー予約</span><h1>フェリーで、<br>島へ行こう。</h1><p>青い海と、特別な時間。<br>伊平屋島・伊是名島へのフェリーを、かんたんに予約できます。</p></div><div class="hero-waves" aria-hidden="true"><svg class="hero-wave hero-wave-back" viewBox="0 0 1440 120" preserveAspectRatio="none"><path d="M0 65C180 15 360 110 540 62S900 18 1080 65s270 46 360 8v47H0Z"/></svg><svg class="hero-wave hero-wave-front" viewBox="0 0 1440 120" preserveAspectRatio="none"><path d="M0 78c210-52 360 32 570 2s340-48 520-5 270 35 350 9v36H0Z"/></svg></div></section><section class="booking-section"><div class="booking-container"><div class="section-heading"><small>CHOOSE YOUR ISLAND</small><h2 class="section-title">今日はどの島へ行きますか？</h2><p>沖縄本島から、海を渡って出会える2つの美しい島。<br>行きたい島を選んで、フェリーの空き状況・ご予約に進めます。</p></div><div class="route-grid island-list">${Object.values(routeMaster).map(routeCard).join('')}</div><section class="today"><div class="row"><div><small>お知らせ</small><h2>本日の運航情報（表示例）</h2></div><span class="status unknown">DEMO</span></div><p class="notice">公式情報ではなくプロトタイプ用デモデータです。ご利用時は各村の公式運航情報をご確認ください。</p></section></div></section></div>`;document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>startBooking(b.dataset.route))}
function routeCard(r){const description=r.id==='iheya'?'美しい海と、のどかな集落。自然と文化が息づく、てるしの島。':'尚円王ゆかりの歴史と、手つかずの自然が残る島。';return`<article class="route-card island-card"><div class="island-media"><div class="art" role="img" aria-label="${r.name}の海とフェリー"></div></div><div class="island-info"><div class="island-title"><span>${r.symbol}</span><div><h2>${r.name}</h2><small>${r.id==='iheya'?'IHEYA ISLAND':'IZENA ISLAND'}</small></div></div><p class="island-description">${description}</p><div class="island-journey">⛴ <b>${r.mainlandPort}</b> から ${durationLabel(r.durationMinutes)}</div></div><div class="island-actions"><button class="primary" data-route="${r.id}">▣ ${r.name}のフェリーを予約する　›</button></div></article>`}
function startBooking(routeId){Object.assign(state,{...defaults,routeId,date:isoDate(1),returnDate:isoDate(3),bookingContact:{...defaults.bookingContact},passengers:[],errors:{}});persist();booking(true)}
function booking(push=false,animate=true){const r=routeMaster[state.routeId];if(!r)return home();if(state.trip==='roundTrip'&&state.returnDate<=state.date)state.returnDate=addDays(state.date,1);normalizePassengers();const progress=Math.round(state.step/(labels.length-1)*100),currentScroll=scrollY;app.innerHTML=`<section class="screen booking-wrap ${animate?'':'no-transition'}" style="--voyage-progress:${progress}%"><div class="booking-head"><div class="booking-hero-copy"><h1>フェリーで、<br>島へ行こう。</h1><p>青い海と、特別な時間。</p></div><span class="status unknown">${r.onlineBookingStatus==='proposed'?'DEMO・構想':'DEMO'}</span></div><div class="booking-body">${selectionSummary(r)}<div class="voyage-progress" aria-label="予約の進み具合 ${state.step+1}/${labels.length}"><span>出発</span><div class="voyage-line"><i></i><b aria-hidden="true">⛴</b></div><span>${r.name}</span></div><div class="stepper">${labels.map((label,i)=>`<span class="${i<=state.step?'on':''}${i===state.step?' current':''}"><i></i><small>${label}</small></span>`).join('')}</div><div class="panel step-${state.step}"><small>STEP ${state.step+1} / ${labels.length}</small>${stepContent(r)}</div><p class="footer-note">操作体験用プロトタイプです。決済・予約登録・個人情報送信は行いません。</p></div></section>`;bindBooking(r);persist();if(push){history.pushState({booking:true,step:state.step},'',`#booking-${state.step}`);scrollTo({top:0,behavior:'instant'})}else scrollTo({top:currentScroll,behavior:'instant'})}
function selectionSummary(r){const d=directionInfo(r),items=[];if(state.step>0)items.push([`${d.from} → ${d.to}`,0]);if(state.step>1)items.push([state.trip==='roundTrip'?'往復':'片道',1]);if(state.step>2)items.push([state.trip==='roundTrip'?`${state.date} → ${state.returnDate}`:state.date,2]);if(state.step>4)items.push([`大人${state.adult}名・小人${state.child}名`,4]);return items.length?`<div class="booking-summary"><b>${r.name}</b>${items.map(x=>`<span>${x[0]} <button data-jump="${x[1]}">変更</button></span>`).join('')}</div>`:''}
const error=key=>state.errors[key]?`<p class="field-error" role="alert">${state.errors[key]}</p>`:'';

function stepContent(r){const d=directionInfo(r);
 if(state.step===0)return`<h2>どちらから出発しますか？</h2><div class="choice-grid"><button class="choice ${state.direction==='outbound'?'selected':''}" data-direction="outbound"><strong>${r.mainlandPort} → ${r.islandPort}</strong>本島側から島へ</button><button class="choice ${state.direction==='inbound'?'selected':''}" data-direction="inbound"><strong>${r.islandPort} → ${r.mainlandPort}</strong>島から本島側へ</button></div>${actions()}`;
 if(state.step===1)return`<h2>片道ですか？往復ですか？</h2><div class="choice-grid"><button class="choice ${state.trip==='oneWay'?'selected':''}" data-trip="oneWay"><strong>→ 片道</strong>行きの便のみ</button><button class="choice ${state.trip==='roundTrip'?'selected':''}" data-trip="roundTrip"><strong>⇄ 往復</strong>帰りもまとめて予約</button></div>${actions()}`;
 if(state.step===2)return`<h2>いつ乗りますか？</h2><div class="current-spec">購入日は翌日から30日先までの表示例です</div><div class="date-grid"><label class="field"><b>行き</b>${d.from} → ${d.to}<input type="date" id="date" value="${state.date}" min="${isoDate(1)}" max="${isoDate(30)}">${error('date')}</label>${state.trip==='roundTrip'?`<label class="field"><b>帰り</b>${d.to} → ${d.from}<input type="date" id="return-date" value="${state.returnDate}" min="${addDays(state.date,1)}" max="${isoDate(30)}">${error('returnDate')}</label>`:''}</div>${actions()}`;
 if(state.step===3)return`<h2>どの便に乗りますか？</h2><p class="notice">運航状態と予約受付状態は別々に表示しています。</p><h3>${d.from} → ${d.to}</h3><div class="sailings">${sailingCards(r,d.key,'out')}</div>${state.trip==='roundTrip'?`<h3 class="direction-title return">帰り：${d.to} → ${d.from}</h3><div class="sailings">${sailingCards(r,d.reverseKey,'return')}</div>`:''}${error('sailing')}${actions()}`;
 if(state.step===4){const max=maxPassengers(r);return`<h2>何名で乗りますか？</h2><p class="notice">選択便の残席に応じて予約可能人数を確認します（上限 ${max}名）。</p><div class="controls">${counter('adult','大人（12歳以上）',state.adult)}${counter('child','小人（6〜11歳）',state.child)}${error('passengers')}<div class="row"><h3>概算合計</h3><div class="price">${yen(total(r))}</div></div></div>${actions()}`}
 if(state.step===5)return`<h2>代表者と乗船者を入力</h2><section class="contact-fields"><h3>代表者情報</h3><label class="field">氏名<input id="contact-name" value="${escapeHtml(state.bookingContact.name)}">${error('name')}</label><label class="field">電話番号<input id="contact-tel" value="${escapeHtml(state.bookingContact.tel)}" inputmode="tel">${error('tel')}</label><label class="field">メールアドレス<input id="contact-email" value="${escapeHtml(state.bookingContact.email)}" type="email">${error('email')}</label></section><section class="passenger-fields"><h3>乗船者情報</h3>${state.passengers.map((p,i)=>`<label class="field">乗船者${i+1}（${p.type==='adult'?'大人':'小人'}）<input data-passenger="${i}" value="${escapeHtml(p.name)}">${error(`passenger-${i}`)}</label>`).join('')}</section>${actions()}`;
 if(state.step===6)return confirmView(r);
 if(state.step===7)return`<h2>もうすぐ予約完了です</h2><p>内容を確認して、事前決済へお進みください。</p><div class="hold-banner"><b>⏱ 予約枠を仮確保中</b><span>残り 09:42</span></div><p class="notice">決済成功で予約確定します。失敗・時間切れの場合は予約枠を開放します。</p><div class="payment-methods"><label><input type="radio" name="payment" checked> クレジットカード</label><label><input type="radio" name="payment"> Apple Pay</label><label><input type="radio" name="payment"> Google Pay</label></div><div class="pay-demo"><small>DEMO PAYMENT</small><h3>お支払い金額 ${yen(total(r))}</h3></div>${actions('デモ決済を完了')}`;
 return ticketView(r)}
const counter=(key,label,value)=>`<div class="counter"><b>${label}</b><div><button data-count="${key}:-1">−</button><strong>${value}</strong><button data-count="${key}:1">＋</button></div></div>`,actions=(next='次へ')=>`<div class="actions">${state.step?'<button class="secondary" data-prev>戻る</button>':'<span></span>'}<button class="primary" data-next>${next} →</button></div>`;
function sailingCards(r,key,kind){const ports=key==='outbound'?{from:r.mainlandPort,to:r.islandPort}:{from:r.islandPort,to:r.mainlandPort};return operation(r,key).map((op,i)=>{const cap=capacity(r,key,i),reserve=bookingStatus(r,key,i),selected=(kind==='return'?state.returnSailing:state.sailing)===i,disabled=['full','closed','unavailable'].includes(reserve)||op.operationStatus==='cancelled',reason=op.operationStatus==='cancelled'?'本便は欠航しています':reserve==='full'?'満席のため選択できません':reserve==='closed'?'オンライン予約受付は終了しました':reserve==='unavailable'?'オンライン予約対象外です':'';return`<button class="sailing-card ${selected?'selected':''}" data-${kind==='return'?'return-':''}sailing="${i}" ${disabled?'disabled':''}>${statusBadge(op.operationStatus,`運航：${operationLabels[op.operationStatus]}`)} ${statusBadge(reserve,`予約：${reservationLabels[reserve]}`)}${op.operationStatus==='changed'?`<div class="time-change">変更前 ${op.scheduledDeparture} <b>→ 変更後 ${op.departure}</b></div>`:''}<div class="sailing-route"><span><small>${ports.from}</small><b>${op.departure}</b></span><i aria-hidden="true">〜 ⛴ 〜</i><span><small>${ports.to}</small><b>${op.arrival}</b></span></div><p>${durationLabel(r.durationMinutes)}</p><div class="stock"><b>残席 ${cap.remaining}</b><small>定員${r.passengerCapacity}名・予約人数${cap.reserved}名</small></div><strong>${reason||selected?'✓ この便を選択中':'この便を選ぶ'}</strong>${reason?`<small class="disabled-reason">${reason}</small>`:''}</button>`}).join('')}
function selectedCapacity(r,back=false){const d=directionInfo(r),key=back?d.reverseKey:d.key,i=back?state.returnSailing:state.sailing;return i==null?null:capacity(r,key,i)}
function maxPassengers(r){return Math.min(selectedCapacity(r)?.remaining??0,state.trip==='roundTrip'?(selectedCapacity(r,true)?.remaining??0):Infinity)}
function normalizePassengers(){const wanted=[...Array(state.adult).fill('adult'),...Array(state.child).fill('child')];state.passengers=wanted.map((type,i)=>state.passengers[i]?.type===type?state.passengers[i]:{type,name:''})}
function fareTotal(r){return state.adult*r.fare.adult[state.trip==='roundTrip'?'roundTrip':'oneWay']+state.child*r.fare.child[state.trip==='roundTrip'?'roundTrip':'oneWay']}
const taxTotal=r=>state.adult*r.fare.environmentTaxRule.amount,total=r=>fareTotal(r)+taxTotal(r);
function confirmView(r){const d=directionInfo(r),out=operation(r,d.key)[state.sailing],back=state.trip==='roundTrip'?operation(r,d.reverseKey)[state.returnSailing]:null;return`<h2>予約内容を確認</h2><div class="summary"><div><span>航路</span><b>${d.from} → ${d.to}</b></div><div><span>行き</span><b>${state.date} ${out.departure}</b></div>${back?`<div><span>帰り</span><b>${state.returnDate} ${back.departure}</b></div>`:''}<div><span>人数</span><b>大人${state.adult}名・小人${state.child}名</b></div><div><span>代表者</span><b>${escapeHtml(state.bookingContact.name)}</b></div><div><span>乗船運賃</span><b>${yen(fareTotal(r))}</b></div><div><span>環境協力税</span><b>${yen(taxTotal(r))}<small>${r.fare.environmentTaxRule.note}</small></b></div><div><span>合計</span><b class="price">${yen(total(r))}</b></div></div><details class="conditions"><summary>キャンセル・返金条件</summary><p>自己都合：手数料 ${yen((state.adult+state.child)*r.fare.cancelFeePerPassenger)}／返金予定 ${yen(Math.max(0,total(r)-(state.adult+state.child)*r.fare.cancelFeePerPassenger))}</p><p>欠航時の返金は別処理です。</p></details>${actions('決済へ')}`}
function ticketView(r){const d=directionInfo(r),out=operation(r,d.key)[state.sailing];return`<div class="ticket arrival-ticket"><div class="arrival-mark" aria-hidden="true">✓</div><h2>予約が完了しました！</h2><p>島への船旅をお楽しみください。</p><div class="boarding-pass"><div class="pass-head"><div><small>FERRY BOARDING PASS</small><b>${r.name}行き・${r.ship}</b></div>${statusBadge('open','未使用')}</div><canvas class="qr" width="290" height="290"></canvas><b class="qr-id">DEMO-${r.id.toUpperCase()}-1029</b><div class="summary"><div><span>航路</span><b>${d.from} → ${d.to}</b></div><div><span>乗船日</span><b>${state.date}</b></div><div><span>出航時刻</span><b>${out.departure}</b></div><div><span>乗船者</span><b>${state.passengers.map(x=>escapeHtml(x.name)).join('、')}</b></div><div><span>乗船状態</span><b>未使用</b></div></div><button class="primary" data-lookup>予約を確認する</button></div>`}

function validate(r){state.errors={};if(state.step===2&&state.trip==='roundTrip'&&state.returnDate<=state.date)state.errors.returnDate='帰りは行きの翌日以降を選択してください。';if(state.step===3){if(state.sailing==null)state.errors.sailing='行きの便を選択してください。';if(state.trip==='roundTrip'&&state.returnSailing==null)state.errors.sailing='帰りの便も選択してください。'}if(state.step===4){const n=state.adult+state.child,max=maxPassengers(r);if(!n)state.errors.passengers='大人または小人を1名以上選択してください。';else if(n>max)state.errors.passengers=`選択人数が残席${max}名を超えています。`}if(state.step===5){if(!state.bookingContact.name.trim())state.errors.name='代表者氏名を入力してください。';if(!state.bookingContact.tel.trim())state.errors.tel='電話番号を入力してください。';if(!state.bookingContact.email.trim())state.errors.email='メールアドレスを入力してください。';else if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(state.bookingContact.email))state.errors.email='正しいメール形式で入力してください。';state.passengers.forEach((p,i)=>{if(!p.name.trim())state.errors[`passenger-${i}`]=`乗船者${i+1}の氏名を入力してください。`})}return!Object.keys(state.errors).length}
function captureInputs(){const n=document.querySelector('#contact-name'),t=document.querySelector('#contact-tel'),e=document.querySelector('#contact-email');if(n)state.bookingContact.name=n.value;if(t)state.bookingContact.tel=t.value;if(e)state.bookingContact.email=e.value;document.querySelectorAll('[data-passenger]').forEach(x=>state.passengers[+x.dataset.passenger].name=x.value)}
function bindBooking(r){document.querySelectorAll('[data-direction]').forEach(x=>x.onclick=()=>{state.direction=x.dataset.direction;state.sailing=state.returnSailing=null;booking(false,false)});document.querySelectorAll('[data-trip]').forEach(x=>x.onclick=()=>{state.trip=x.dataset.trip;booking(false,false)});document.querySelectorAll('[data-sailing]').forEach(x=>x.onclick=()=>{state.sailing=+x.dataset.sailing;booking(false,false)});document.querySelectorAll('[data-return-sailing]').forEach(x=>x.onclick=()=>{state.returnSailing=+x.dataset.returnSailing;booking(false,false)});document.querySelectorAll('[data-count]').forEach(x=>x.onclick=()=>{const[k,v]=x.dataset.count.split(':');state[k]=Math.max(0,state[k]+Number(v));normalizePassengers();booking(false,false)});document.querySelectorAll('[data-jump]').forEach(x=>x.onclick=()=>{state.step=+x.dataset.jump;booking(true)});document.querySelector('[data-prev]')?.addEventListener('click',()=>{state.step=Math.max(0,state.step-1);booking(true)});document.querySelector('[data-next]')?.addEventListener('click',()=>{captureInputs();if(!validate(r)){booking(false,false);return}state.step=Math.min(8,state.step+1);booking(true)});document.querySelector('#date')?.addEventListener('change',e=>{state.date=e.target.value;if(state.returnDate<=state.date)state.returnDate=addDays(state.date,1)});document.querySelector('#return-date')?.addEventListener('change',e=>state.returnDate=e.target.value);document.querySelector('[data-lookup]')?.addEventListener('click',lookup);if(state.step===8)drawQr(document.querySelector('.qr'),`DEMO-${r.id}-${state.date}-${state.sailing}`)}

function lookup(){document.body.classList.remove('admin-mode');location.hash='lookup';app.innerHTML=`<section class="screen booking-wrap lookup-screen"><div class="booking-head"><div><button class="secondary" data-home>← トップ</button><h1>予約を確認する</h1><p>予約番号から乗船券・変更・返金状況を確認</p></div></div><div class="panel"><label class="field">予約番号<input id="lookup-number" value="DEMO-1042"></label><button class="primary" data-find>確認する</button><div id="lookup-result"></div></div></section>`;document.querySelector('[data-find]').onclick=showBooking;bindGlobal()}
function showBooking(){const id=document.querySelector('#lookup-number').value.trim().toUpperCase(),b=demoBookings[id],target=document.querySelector('#lookup-result');if(!b){target.innerHTML='<p class="field-error">予約が見つかりません。</p>';return}const r=routeMaster[b.routeId],cancelled=b.status==='cancelledByOperator',d=directionInfo(r,b.direction);target.innerHTML=`<section class="reservation-detail ${cancelled?'cancelled-booking':''}">${cancelled?'<div class="urgent"><h2>ご予約の便は欠航となりました</h2><p>返金状況と便変更をご確認ください。</p></div>':''}<h2>${b.bookingNumber}</h2><div class="summary"><div><span>航路</span><b>${d.from} → ${d.to}</b></div><div><span>乗船</span><b>${b.date} ${b.departure}</b></div><div><span>乗船者</span><b>${b.passengers.join('、')}</b></div><div><span>QR状態</span><b>${b.qrStatus==='unused'?'未使用':'欠航・利用不可'}</b></div><div><span>返金状況</span><b>${b.refundStatus}</b></div></div><div class="actions"><a class="secondary" href="${r.official}" target="_blank">公式運航情報</a><button class="primary">${cancelled?'他便へ変更':'QR乗船券を表示'}</button></div></section>`}

function admin(){document.body.classList.add('admin-mode');location.hash='admin';document.querySelector('.brand-label').textContent='職員管理システム';const rows=Object.values(routeMaster).flatMap(r=>['outbound','inbound'].flatMap(key=>operation(r,key).map((op,i)=>({r,op,cap:capacity(r,key,i),reserve:bookingStatus(r,key,i)}))));app.innerHTML=`<section class="screen admin"><div class="admin-identity"><span>🔒 職員専用デモ</span><b>権限：システム管理者</b></div><div class="row"><div><small>STAFF CONSOLE</small><h1>運航・予約ダッシュボード</h1><p>両村の運航と予約枠を一元管理</p></div><button class="secondary" data-home>利用者画面 ↗</button></div><section class="alerts"><div class="row"><h2>今日確認すること</h2><b>5件</b></div><ul><li class="warn">運航情報が未更新（デモモード）</li><li class="warn">残席10名以下の便があります</li><li>決済エラー 3件</li><li>返金未完了 1件</li><li class="bad">欠航便の通知状況を確認してください</li></ul></section><div class="metrics">${[['本日の予約','86件'],['乗船予定','142人'],['返金対応','1件'],['通知待ち','2件']].map(x=>`<article class="metric"><small>${x[0]}</small><b>${x[1]}</b></article>`).join('')}</div><div class="table"><h2>便ごとの定員・残席・予約枠管理</h2><table><thead><tr><th>航路</th><th>便</th><th>定員</th><th>予約人数</th><th>残席</th><th>運航状態</th><th>予約受付</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.r.name}</td><td>${x.op.departure}</td><td>${x.r.passengerCapacity}</td><td>${x.cap.reserved}</td><td>${x.cap.remaining}</td><td>${operationLabels[x.op.operationStatus]}</td><td>${reservationLabels[x.reserve]}</td></tr>`).join('')}</tbody></table></div><section class="chart-card"><h2>運航状況の手動変更</h2><div class="filters"><label>対象便<select><option>伊平屋 11:00</option><option>伊是名 16:30</option></select></label><label>状態<select><option>通常運航</option><option>時刻変更</option><option>欠航</option><option>臨時便</option><option>運航未定</option></select></label><button class="primary" data-manual>変更を記録</button></div><p class="notice">管理者名・日時・変更前後を監査ログへ保存する設計です。</p></section><div class="table"><h2>11:00便 乗船者一覧</h2><p>予約人数68名／乗船済み52名／未乗船16名</p><table><thead><tr><th>予約番号</th><th>氏名</th><th>区分</th><th>乗船状態</th><th>QR状態</th></tr></thead><tbody><tr><td>DEMO-1042</td><td>山城 花子</td><td>大人</td><td>未乗船</td><td>未使用</td></tr><tr><td>DEMO-1043</td><td>山城 海</td><td>小人</td><td>乗船済み</td><td>乗船済み</td></tr></tbody></table></div><section class="future-feature"><b>将来対応：車両オンライン予約</b><p>車両種別・ナンバー・車両長・往復別の車両予約枠を管理できる構造を保持します。</p></section></section>`;document.querySelector('[data-manual]').onclick=()=>alert('デモ：管理者・日時・変更前後を操作履歴へ記録します');bindGlobal()}

function drawQr(canvas,value){if(!canvas)return;const c=canvas.getContext('2d'),n=29,q=4,s=canvas.width/(n+q*2);let seed=[...value].reduce((a,x)=>Math.imul(a^x.charCodeAt(0),16777619)>>>0,2166136261);const rand=()=>{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return(seed>>>0)/4294967296};c.fillStyle='#fff';c.fillRect(0,0,canvas.width,canvas.height);c.fillStyle='#071c2a';for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(rand()>.5)c.fillRect((x+q)*s,(y+q)*s,Math.ceil(s),Math.ceil(s))}
function closeMenu(){document.querySelector('#site-menu')?.classList.remove('open');document.querySelector('.menu-toggle')?.setAttribute('aria-expanded','false')}
function bindGlobal(){document.querySelectorAll('[data-home]').forEach(x=>x.onclick=()=>{closeMenu();home()});document.querySelectorAll('[data-admin]').forEach(x=>x.onclick=()=>{closeMenu();admin()});document.querySelectorAll('[data-lookup-nav]').forEach(x=>x.onclick=()=>{closeMenu();lookup()})}
document.querySelector('.menu-toggle')?.addEventListener('click',e=>{const m=document.querySelector('#site-menu'),open=m.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))});document.addEventListener('click',e=>{if(!e.target.closest('.nav'))closeMenu()});window.addEventListener('popstate',e=>{if(e.state?.booking&&state.routeId){state.step=e.state.step;booking(false)}else home()});bindGlobal();location.hash==='#admin'?admin():location.hash==='#lookup'?lookup():home();
